import Foundation
import SwiftUI

// MARK: - Training Plan

struct TrainingPlan: Identifiable, Codable {
    let id: UUID
    let name: String
    let goal: String
    let level: FitnessLevel
    var weeks: [TrainingWeek]
    let createdAt: Date
    let startDate: Date?
    let isActive: Bool

    init(
        id: UUID = UUID(),
        name: String,
        goal: String,
        level: FitnessLevel,
        weeks: [TrainingWeek],
        createdAt: Date = Date(),
        startDate: Date? = nil,
        isActive: Bool = false
    ) {
        self.id = id
        self.name = name
        self.goal = goal
        self.level = level
        self.weeks = weeks
        self.createdAt = createdAt
        self.startDate = startDate
        self.isActive = isActive
    }

    var lastAdaptationDate: Date?
    var adaptationAssessment: String?

    var totalWeeks: Int {
        weeks.count
    }

    var totalWorkouts: Int {
        weeks.flatMap { $0.days }.filter { $0.workout != nil }.count
    }

    var isCompleted: Bool {
        let workoutDays = weeks.flatMap { $0.days }.filter { $0.workout != nil }
        return !workoutDays.isEmpty && workoutDays.allSatisfy { $0.isCompleted }
    }

    var currentWeekIndex: Int? {
        guard let start = startDate else { return nil }
        let daysSinceStart = Calendar.current.dateComponents([.day], from: start, to: Date()).day ?? 0
        let weekIndex = daysSinceStart / 7
        return weekIndex < weeks.count ? weekIndex : nil
    }
}

// MARK: - Training Week

struct TrainingWeek: Identifiable, Codable {
    let id: UUID
    let weekNumber: Int
    let phase: TrainingPhase
    var days: [TrainingDay]
    let weeklyVolume: Double? // Total distance in km
    let notes: String?

    init(
        id: UUID = UUID(),
        weekNumber: Int,
        phase: TrainingPhase,
        days: [TrainingDay],
        weeklyVolume: Double? = nil,
        notes: String? = nil
    ) {
        self.id = id
        self.weekNumber = weekNumber
        self.phase = phase
        self.days = days
        self.weeklyVolume = weeklyVolume
        self.notes = notes
    }

    var workoutCount: Int {
        days.filter { $0.workout != nil }.count
    }

    var restDayCount: Int {
        days.filter { $0.isRestDay }.count
    }
}

// MARK: - Training Day

struct TrainingDay: Identifiable, Codable {
    let id: UUID
    let dayOfWeek: DayOfWeek
    let workout: PlannedWorkout?
    var isRestDay: Bool { workout == nil }
    var isCompleted: Bool
    var completedWorkoutId: String? // Link to actual HKWorkout

    private enum CodingKeys: String, CodingKey {
        case id, dayOfWeek, workout, isCompleted, completedWorkoutId
    }

    init(
        id: UUID = UUID(),
        dayOfWeek: DayOfWeek,
        workout: PlannedWorkout? = nil,
        isCompleted: Bool = false,
        completedWorkoutId: String? = nil
    ) {
        self.id = id
        self.dayOfWeek = dayOfWeek
        self.workout = workout
        self.isCompleted = isCompleted
        self.completedWorkoutId = completedWorkoutId
    }
}

// MARK: - Planned Workout

struct PlannedWorkout: Identifiable, Codable {
    let id: UUID
    let type: WorkoutType
    let name: String
    let description: String
    let targetDuration: TimeInterval? // in seconds
    let targetDistance: Double? // in meters
    let targetPace: String? // e.g., "5:30/km"
    let steps: [PlannedWorkoutStep]
    let intensity: WorkoutIntensity

    init(
        id: UUID = UUID(),
        type: WorkoutType,
        name: String,
        description: String,
        targetDuration: TimeInterval? = nil,
        targetDistance: Double? = nil,
        targetPace: String? = nil,
        steps: [PlannedWorkoutStep] = [],
        intensity: WorkoutIntensity = .moderate
    ) {
        self.id = id
        self.type = type
        self.name = name
        self.description = description
        self.targetDuration = targetDuration
        self.targetDistance = targetDistance
        self.targetPace = targetPace
        self.steps = steps
        self.intensity = intensity
    }

    var formattedDuration: String {
        guard let duration = targetDuration else { return "" }
        let minutes = Int(duration) / 60
        if minutes < 60 {
            return "\(minutes) min"
        }
        let hours = minutes / 60
        let remainingMinutes = minutes % 60
        return "\(hours)h \(remainingMinutes)min"
    }

    var formattedDistance: String {
        guard let distance = targetDistance else { return "" }
        return String(format: "%.1f km", distance / 1000)
    }
}

// MARK: - Planned Workout Step

struct PlannedWorkoutStep: Identifiable, Codable {
    let id: UUID
    let type: PlannedStepType
    let duration: TimeInterval? // in seconds
    let distance: Double? // in meters
    let targetPace: String?
    let description: String

    init(
        id: UUID = UUID(),
        type: PlannedStepType,
        duration: TimeInterval? = nil,
        distance: Double? = nil,
        targetPace: String? = nil,
        description: String
    ) {
        self.id = id
        self.type = type
        self.duration = duration
        self.distance = distance
        self.targetPace = targetPace
        self.description = description
    }
}

// MARK: - Enums

enum FitnessLevel: String, Codable, CaseIterable {
    case beginner
    case intermediate
    case advanced

    var displayName: String {
        switch self {
        case .beginner:
            return String(localized: "Beginner", comment: "Fitness level - beginner")
        case .intermediate:
            return String(localized: "Intermediate", comment: "Fitness level - intermediate")
        case .advanced:
            return String(localized: "Advanced", comment: "Fitness level - advanced")
        }
    }
}

enum TrainingPhase: String, Codable, CaseIterable {
