        case .peak:
            return String(localized: "Peak Phase", comment: "Training phase - peak")
        case .taper:
            return String(localized: "Taper", comment: "Training phase - taper")
        case .recovery:
            return String(localized: "Recovery", comment: "Training phase - recovery")
